INSERT INTO `informe_trabajo` VALUES (1,1,16,'2026-02-02',1,1,NULL,'23','2026-02-02 18:31:36',1,'HORAS DE TRABAJO\r\n13.- Cuando presiono el bot?n Horas de Trabajo de inmediato me va a permitir entrar a la siguiente ventana que est? en la Imagen # 14\r\nObservaci?n: Se debe tener en cuenta lo siguiente:\r\nCuando se ingrese a cada uno de los Empleado deber? ponerle la Hora Entrada y Hora Salida y el sistema autom?ticamente deber? CALCULAR poniendo en las Horas Normales y Horas Extras sin necesidad de digitarlo.\r\nLas Horas Normales siempre son las 9 Horas Diarias de lunes a viernes de las cuales son 8 horas de trabajo m?s 1 Hora de almuerzo.\r\nLas Horas Extras son despu?s de haber cumplido las 9 Horas Normales en el d?a de lunes a viernes. Los d?as s?bados tambi?n son Horas Extras.\r\nLas Horas Extraordinarias son los d?as Domingos y d?as Feriados que tambi?n pueden caer entre semana de lunes a viernes.\r\n\r\n'),(2,1,16,'2026-02-02',1,1,NULL,'222','2026-02-02 18:33:23',1,NULL),(3,1,3,'2026-01-18',5,5,NULL,'','2026-02-12 15:06:24',1,'se entrego este articulo'),(4,1,17,'2026-01-19',5,5,NULL,'se realiza los informes','2026-02-26 22:08:39',1,'zzzzzzzzzzzzzzzzzzzzzzzzz'),(5,1,18,'2026-01-20',5,5,NULL,'xxxx','2026-02-27 11:52:44',1,'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'),(6,1,19,'2026-01-21',5,5,NULL,'pidio material para hacer un trabajo en el sector B','2026-03-09 16:02:30',1,'pidi? material para hacer un trabajo en el sector B'),(7,1,20,'2026-01-22',1,1,NULL,'xxxxxxxxxxxx','2026-03-09 16:30:56',1,NULL),(8,1,20,'2026-01-22',5,5,NULL,'xxxxxxxxxx','2026-03-09 16:31:20',1,'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'),(9,1,21,'2026-01-23',5,5,NULL,'xxxxxxxxx','2026-03-09 16:35:36',1,'xxxxxxxxxxxxxxxxxxxxxxxxxxxx'),(10,1,22,'2026-01-24',5,5,NULL,'xxxxxxxx','2026-03-09 16:41:57',1,'xxxxxxxxxxxxxxxxxxxx'),(11,1,22,'2026-01-24',5,5,NULL,'','2026-03-09 16:43:32',1,'xxxxxxxxxxxxxxxxxxx'),(12,1,23,'2026-01-25',5,5,NULL,'xxxxxxxxxxxx',