INSERT INTO `liquidacion_trabajo` VALUES (3,3,3,NULL,NULL,NULL,NULL,NULL,'Detallo a continuaci?n los trabajos generales que se realizaron:				\r\n*Armado y montaje de transferencia autom?tica de 320amp				\r\n*Armado de tablero de distribuci?n 220V (5 KVA) 				\r\n*Armado y montaje de bandejas portacables de 20 x 10 desde tablero de transferencia autom?tica a generador 				\r\n*Cableado y conexionado de dos ternas de cable 4/0 desde generador a transferencia autom?tica 				\r\n*Cableado y conexionado de dos ternas de cable 4/0 desde transformador pad mounted a tablero de transferencia autom?tica 				\r\n*Integraci?n de control de datakom para la transferencia autom?tica (se?ales de encendido, resistencia cahqueta de calentamiento y cargador de bater?as)	Puesta en marcha.','Se tiene que adjuntar el trabajo de Iv?n Hern?ndez en la integraci?n del control de la transferencia autom?tica.','2026-04-07 21:14:07','2026-04-09 16:34:00',1),(4,3,9,NULL,NULL,NULL,NULL,NULL,'Detallo a continuaci?n los trabajos generales que se realizaron:				\r\n*Armado y montaje de transferencia autom?tica de 320amp				\r\n*Armado de tablero de distribuci?n 220V (5 KVA) 				\r\n*Armado y montaje de bandejas porta cables de 20 x 10 desde tablero de transferencia autom?tica a generador.				\r\n*Cableado y conexionado de dos ternas de cable 4/0 desde generador a transferencia autom?tica. 				\r\n*Cableado y conexionado de dos ternas de cable 4/0 desde transformador pad mounted a tablero de transferencia autom?tica.				\r\nIntegraci?n de control de datakom para la transferencia autom?tica (se?ales de encendido, resistencia cahqueta de calentamiento y cargador de bater?as). Puesta en marcha.','Se tiene que adjuntar el trabajo de Iv?n Hern?ndez en la integraci?n del control de la transferencia autom?tica','2026-04-07 21:15:54','2026-04-09 16:40:50',1),(5,3,10,NULL,NULL,NULL,NULL,NULL,'','','2026-04-09 14:11:55','2026-04-09 14:11:55',1);
