  CONSTRAINT `movimientos_ibfk_4` FOREIGN KEY (`id_sub_tipo_movimiento`) REFERENCES `sub_tipo_movimiento` (`id_sub_tipo_movimiento`)
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
