  CONSTRAINT `stock_productos_bodega_ibfk_1` FOREIGN KEY (`id_producto`) REFERENCES `articulos` (`id_producto`),
  CONSTRAINT `stock_productos_bodega_ibfk_2` FOREIGN KEY (`id_bodega_principal`) REFERENCES `bodegas` (`id_bodega`),
  CONSTRAINT `stock_productos_bodega_ibfk_3` FOREIGN KEY (`id_bodega_secundaria`) REFERENCES `bodegas` (`id_bodega`)
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
